"""Billing for trades. Rate lookups are billed, so the charge is remembered."""
import rates


class TradeBill:
    def __init__(self):
        self._trades = []
        self._charge = None

    def add(self, trade):
        """Add one trade to the bill."""
        self._trades.append(trade)

    def charge(self):
        """Return the total charge: volume times the rate for each trade's desk.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.volume * rates.rate_for(x.desk) for x in self._trades)
        return self._charge


def largest_volume(trades):
    """Return the largest volume, or None when there are no trades."""
    values = [x.volume for x in trades]
    return max(values) if values else None


def group_by_desk(trades):
    """Return a dict from desk to the list of trades with that desk."""
    groups = {}
    for x in trades:
        groups.setdefault(x.desk, []).append(x)
    return groups

